/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; out=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'governed by|governed and|governing law|choice of law|applicable law|governed,|governed\\s*"'$'"',l,re.I):
   out.append('p. '+page+': '+' '.join(lines[i:i+4]))
 print(f.name[:-4])
 print('\\n'.join(out) or 'NO MATCH')
PY"

