/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 lines=f.read_text().replace('\\xa0',' ').splitlines(); page='?'; out=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'Texas|governing law|applicable law\\.|governed by|governed and',l,re.I):
   out.append('p. '+page+': '+' '.join(lines[max(0,i-1):i+3]))
 print(f.name[:-4]); print('\\n'.join(out) or 'NO MATCH')
PY"

